from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];W=Path('./.local/station-realism');C=W/'central-gate-facade-01';O=R/'notes/central-gate-facade';O.mkdir(exist_ok=True)
files={n:C/n for n in ['report.json','serialization.json','normals.json','scope-and-recess-proof.json']};files['spec.json']=W/'central-gate-facade-spec-01/spec.json'
for name in ['recess-source.json','depth-audit.json','rear-plane.json']:files[name]=W/'central-gate-bridge-study-01'/name
for v in ['before','after','close']:files[v+'.png']=C/v/'source.png';files[v+'-receipt.json']=C/v/'projection.json'
files['source-front.png']=W/'central-gate-bridge-study-01/source-front/source.png';files['source-front-receipt.json']=W/'central-gate-bridge-study-01/source-front/projection.json'
manifest=[]
for name,p in files.items():
 b=p.read_bytes();(O/name).write_bytes(b);manifest.append({'file':name,'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)})
(O/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
figs=''.join(f'<figure><a href="{v}.png"><img src="{v}.png" alt="{title}"></a><figcaption>{title}</figcaption></figure>' for v,title in [('before','Before: low stone band and missing square recesses'),('after','After: source boundary and sixteen modeled blind recesses'),('close','Close-up: cut face slabs and recessed backs'),('source-front','Municipal source: bridge and gate line depicted in a flat texture')])
links=''.join(f'<li><a href="{n}">{n}</a></li>' for n in files if n.endswith('.json'))
(O/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Central gate facade correction</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f2ec;color:#24382f;font:16px/1.55 system-ui}main{max-width:1250px;margin:auto;padding:24px}h1{line-height:1.15}a{color:#17654c;overflow-wrap:anywhere}figure{margin:24px 0}img{width:100%;display:block}figcaption{background:#e1e8df;padding:12px;font-size:14px}.status{padding:18px;background:#f2dfb4}li{margin:8px 0}</style><main><a href="../../index.html">Research library</a><h1>Gate facade: corrected stone band and recesses</h1><p>28 September 2026. The dark stone boundary now follows municipal source vertices at Y=5.751988m, replacing the earlier 3.7m assumption. Sixteen square recesses use source X/Y positions and an explicitly inferred 37mm blind depth.</p><p class="status">Uninstalled component study. Existing complete hall/basement and active game assets remain unchanged. These fixed studio views do not establish photorealistic lighting or full-game performance.</p><p>649 records, 10,700 triangles, eight material batches. Closed meshes, normals and browser/native serialization pass; 80 static probes verify recesses. Geometry outside the intended gate walls/returns remains unchanged. See the scope receipt for two previously established physical material-key corrections.</p>'''+figs+'''<h2>The passage behind the opening</h2><p>The source triangle audit finds a rear envelope about 23.7m behind the frontage, but no modeled bridge in the inspected intervening volume. The 5.6m sample returns are incomplete. Current hotel diagrams establish an M3F connection from the free passage to the 2F lobby; identifying the photographed bridge with this route remains an inference. North is down on the hotel diagram.</p><figure><a href="../../maps/granvia-m3f-map.jpg"><img src="../../maps/granvia-m3f-map.jpg" alt="Hotel operator M3F corridor diagram"></a><figcaption>Hotel Granvia Kyoto / JR West Hotels. Current operator schematic, separately undated image; linked July2026 PDF page3 corroborates the route. Reference only, not a metric plan. <a href="https://jrwest-hotels.jp/granvia-kyoto/floor/">Official source</a>.</figcaption></figure><p><a href="../CENTRAL-GATE-FACADE.md">Findings and integration limits</a> · <a href="../../maps/granvia-floor-2026-pdf.pdf">Operator floor map</a> · <a href="../central-gate-hardware/index.html">Hardware prototype</a></p><h2>Evidence</h2><ul>'''+links+'''<li><a href="manifest.json">Published hashes</a></li></ul></main></html>''')
print(O)
